ike every other write path. J12 checks the product''s name\nin the page heading, where it is shown.","tree":{"sha":"20f604886b734318a78ef3bbcf8de99aa7ed5a2d","url":"https://api.github.com/repos/janpfeil/kundenportal-demo/git/trees/20f604886b734318a78ef3bbcf8de99aa7ed5a2d"},"url":"https://api.github.com/repos/janpfeil/kundenportal-demo/git/commits/92eeb5d677bcafeb500441c66f5526430269d948","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/5345175?v=4","events_url":"https://api.github.com/users/janpfeil/events{/privacy}","followers_url":"https://api.github.com/users/janpfeil/followers","following_url":"https://api.github.com/users/janpfeil/following{/other_user}","gists_url":"https://api.github.com/users/janpfeil/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/janpfeil","id":5345175,"login":"janpfeil","node_id":"MDQ6VXNlcjUzNDUxNzU=","organizations_url":"https://api.github.com/users/janpfeil/orgs","received_events_url":"https://api.github.com/users/janpfeil/received_events","repos_url":"https://api.github.com/users/janpfeil/repos","site_admin":false,"starred_url":"https://api.github.com/users/janpfeil/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/janpfeil/subscriptions","type":"User","url":"https://api.github.com/users/janpfeil","user_view_type":"public"},"html_url":"https://github.com/janpfeil/kundenportal-demo/commit/92eeb5d677bcafeb500441c66f5526430269d948","node_id":"C_kwDOUydk39oAKDkyZWViNWQ2NzdiY2FmZWI1MDA0NDFjNjZmNTUyNjQzMDI2OWQ5NDg","parents":[{"html_url":"https://github.com/janpfeil/kundenportal-demo/commit/a4f4fecce06b23d4167424202d8f6cf092cd1393","sha":"a4f4fecce06b23d4167424202d8f6cf092cd1393","url":"https://api.github.com/repos/janpfeil/kundenportal-demo/commits/a4f4fecce06b23d4167424202d8f6cf092cd1393"}],"sha":"92eeb5d677bcafeb500441c66f5526430269d948","url":"https://api.github.com/repos/ja