os_url":"https://api.github.com/users/janpfeil/repos","site_admin":false,"starred_url":"https://api.github.com/users/janpfeil/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/janpfeil/subscriptions","type":"User","url":"https://api.github.com/users/janpfeil","user_view_type":"public"},"comments_url":"https://api.github.com/repos/janpfeil/kundenportal-demo/commits/15ac02a457d5177ad5da7d515d108c76cb8b73e6/comments","commit":{"author":{"date":"2026-10-01T22:53:43Z","email":"jan.pfeil@rypox.net","name":"Jan Pfeil"},"comment_count":0,"committer":{"date":"2026-10-01T22:53:43Z","email":"jan.pfeil@rypox.net","name":"Jan Pfeil"},"message":"Keep the E2E runs'' throw-away accounts out of the operator''s lists\n\nEvery live E2E run registers a few customers at the reserved domain .invalid in\nthe owner tenant; with the new back office they would pile up in the\noperator''s customer and contract lists and figures. Their contracts carry a\nmark from the registration on and both lists leave them out, like the owner\nmails already do.","tree":{"sha":"8195bfab6038353830aeee216ec310c38f40212e","url":"https://api.github.com/repos/janpfeil/kundenportal-demo/git/trees/8195bfab6038353830aeee216ec310c38f40212e"},"url":"https://api.github.com/repos/janpfeil/kundenportal-demo/git/commits/15ac02a457d5177ad5da7d515d108c76cb8b73e6","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/5345175?v=4","events_url":"https://api.github.com/users/janpfeil/events{/privacy}","followers_url":"https://api.github.com/users/janpfeil/followers","following_url":"https://api.github.com/users/janpfeil/following{/other_user}","gists_url":"https://api.github.com/users/janpfeil/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/janpfeil","id":5345175,"login":"janpfeil","node_id":"MDQ6VXNlcjUzNDUxNzU=","organizations_url":"https://api.github.com/users/janpfei