mand way to run all apps together.","tree":{"sha":"f18ad798300988f53c7d685dc4873414910d2f32","url":"https://api.github.com/repos/kamalpatel125/ui-microfrontend/git/trees/f18ad798300988f53c7d685dc4873414910d2f32"},"url":"https://api.github.com/repos/kamalpatel125/ui-microfrontend/git/commits/f7e22bf696f9cd455052d549247323dd56f544f4","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/5058102?v=4","events_url":"https://api.github.com/users/kamalpatel125/events{/privacy}","followers_url":"https://api.github.com/users/kamalpatel125/followers","following_url":"https://api.github.com/users/kamalpatel125/following{/other_user}","gists_url":"https://api.github.com/users/kamalpatel125/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/kamalpatel125","id":5058102,"login":"kamalpatel125","node_id":"MDQ6VXNlcjUwNTgxMDI=","organizations_url":"https://api.github.com/users/kamalpatel125/orgs","received_events_url":"https://api.github.com/users/kamalpatel125/received_events","repos_url":"https://api.github.com/users/kamalpatel125/repos","site_admin":false,"starred_url":"https://api.github.com/users/kamalpatel125/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/kamalpatel125/subscriptions","type":"User","url":"https://api.github.com/users/kamalpatel125","user_view_type":"public"},"html_url":"https://github.com/kamalpatel125/ui-microfrontend/commit/f7e22bf696f9cd455052d549247323dd56f544f4","node_id":"C_kwDOUz0Vj9oAKGY3ZTIyYmY2OTZmOWNkNDU1MDUyZDU0OTI0NzMyM2RkNTZmNTQ0ZjQ","parents":[{"html_url":"https://github.com/kamalpatel125/ui-microfrontend/commit/193f1df40800a2b420948fed0da87dc2bae24de5","sha":"193f1df40800a2b420948fed0da87dc2bae24de5","url":"https://api.github.com/repos/kamalpatel125/ui-microfrontend/commits/193f1df40800a2b420948fed0da87dc2bae24de5"}],"sha":"f7e22bf696f9cd455052d549247323dd56f544f4","url":"https://api.gith